CREATE TABLE IF NOT EXISTS "NotificationPreference" ("userId" uuid PRIMARY KEY REFERENCES "User"(id) ON DELETE CASCADE, channels jsonb NOT NULL DEFAULT '{"in_app":true,"email":true,"push":false}'::jsonb, "quietHoursStart" text, "quietHoursEnd" text, timezone text, "categoryOpts" jsonb NOT NULL DEFAULT '{}'::jsonb, "updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Notification" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "userId" uuid NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, category text NOT NULL, title text NOT NULL, body text NOT NULL, "dedupeKey" text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'QUEUED', "scheduledFor" timestamptz, "createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "DeliveryAttempt" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "notificationId" uuid NOT NULL REFERENCES "Notification"(id) ON DELETE CASCADE, channel text NOT NULL, status text NOT NULL, attempt int NOT NULL, "errorCode" text, "createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
